slides=[dict(id=1,type='hero',title='KI für deinen Arbeitsalltag.',lead='Heute machen wir ganz normale Büroarbeit einfacher.',chapter=0,chapterName='Willkommen',paragraphs=[]),dict(id=2,type='prep',title='Vor dem Seminar: einmal alles testen.',lead='Wenn etwas fehlt, kontaktiere ITP.',chapter=0,chapterName='Vorbereitung',paragraphs=[]),dict(id=3,type='intro',title='Du musst keine Technik lernen.',lead='Du sagst, was du brauchst. Wir schauen uns ein Beispiel an. Dann probierst du es selbst.',chapter=0,chapterName='So läuft es ab',paragraphs=['Wir starten mit erfundenen Daten aus einem Handwerksbetrieb. Bei der Mail-Übung kannst du eine passende eigene Mail von heute verwenden oder unser fiktives Beispiel nutzen.'])]
for i,m in enumerate(modules,1):
 for typ in ['lesson','demo','challenge']:
  s=dict(m,id=len(slides)+1,type=typ,chapter=i,chapterName=m['name'],lead=m['title'],paragraphs=[m['explain']],steps=['Deine Unterlagen','Dein Auftrag','Das Ergebnis','Kurz prüfen'],goal=m['task'],criteria='; '.join(m['success']),hints=[m['prompt']],bonus='')
  if typ=='demo':s['title']=m['example'];s['lead']=m['example']
  if typ=='challenge':s['title']='Jetzt probierst du es.';s['lead']=m['task']
  slides.append(s)
slides.append(dict(id=len(slides)+1,type='outro',title='Welche Aufgabe wird morgen einfacher?',lead='Such dir eine Sache aus deinem Arbeitsalltag aus. Genau damit fängst du an.',chapter=0,chapterName='Zum Abschluss',paragraphs=['Wenn du mehrere Themen kombinieren möchtest, probiere die freiwillige Abschlussaufgabe Parkblick.']))
